17: let target;
18: try { target = new URL(url); } catch {}
19: if (!target || !/^https?:$/.test(target.protocol)) {
20:   console.error('CAPTURE_URL must be an absolute HTTP(S) URL.');
21:   process.exitCode = 1;
22: } else if (relativeOutput === '' || relativeOutput === '..' || (!relativeOutput.startsWith('..' + sep) && !relativeOutput.startsWith(sep))) {
23:   console.error('CAPTURE_DIR must be outside the project source directory.');
24:   process.exitCode = 1;
25: } else {
26:   const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
27:   let browser;
28:   let exitCode = 1;
29:   try {
30:     const require = createRequire(join(runtime, 'package.json'));
31:     const { chromium } = require('playwright');
32:     const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'));
33:     if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
34:     mkdirSync(output, { recursive: true });
35:     browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
36:     for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
