49:       } catch (error) {
50:         error.exitCode = 75;
51:         throw error;
52:       }
53:       if (!response?.ok()) {
54:         const status = response?.status();
55:         const temporary = !response || [408, 429, 500, 502, 503, 504].includes(status) || status >= 500;
56:         const error = new Error(`HTTP ${status ?? 'no response'} loading ${url}`);
57:         error.exitCode = temporary ? 75 : 1;
58:         throw error;
59:       }
