61:       await page.locator('#fish-count').waitFor({ state: 'visible' });
62:       await page.waitForFunction(() => document.fonts.status === 'loaded', { timeout: 30000 });
63:       await page.waitForTimeout(1200);
64:       const rendered = await page.locator('#ocean').evaluate(canvas => ({
